-- Device identity. Generated by `rebench new`; edit freely.
-- product_id, manufacturer and version_number must match what you register
-- with Reason Studios before a public build. These values are fine for local
-- Recon testing.

format_version = "1.0"

-- At most 40 / 20 / 10 characters. Reason Studios asks for "[product name]
-- [short description]" as the long name, without the manufacturer.
long_name   = "@@LONG_NAME@@"
medium_name = "@@MEDIUM_NAME@@"
short_name  = "@@SHORT_NAME@@"

product_id     = "@@PRODUCT_ID@@"
manufacturer   = "@@MANUFACTURER@@"
version_number = "1.0.0d1"

device_type = "creative_fx"
-- Pick from the device category guidelines in the scripting specification
-- (Dist, Dynamics, EQ, Filter, Modulation, Stereo ...); acceptance testing checks it.
device_categories = { "Misc" }

supports_patches = false
device_height_ru = @@HEIGHT_RU@@

-- The scripting specification asks for exactly this colour.
automation_highlight_color = { r = 60, g = 255, b = 2 }

accepts_notes = false
auto_create_track = false
auto_create_note_lane = false
supports_performance_automation = false
